/* ===== Examinations: exam setup and timetable, question paper workflow, seating and hall tickets, invigilation, marks with moderation, results and report cards, supplementary exams, analysis ===== */
const EX_ACT = {};
Store.init({ exam: { cfg: { pass: 33, graceMax: 5, blockOverdue: false, perInv: 30, suppCap: true }, rooms: {}, exams: [], papers: [], seats: [], duty: [], marks: {}, mst: {}, ack: {}, interv: [], log: [] } });
const exD = () => Store.get('exam');
const exCan = k => can('exam', k);
const exMgr = () => exCan('Approve');
