const exAud = (a, o) => audit('Examinations', a, o || {});
function exLog(d, bid, action, o, reason) { const u = App.user || {}; d.log.unshift({ id: 'XL' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5), at: nowIso(), bid, branch: (acBr(bid) || {}).name || '', user: u.name || '—', role: u.role || '', action, old: o && o.old != null ? String(o.old) : '', new: o && o.new != null ? String(o.new) : '', reason: reason || '' }); d.log = d.log.slice(0, 3000); }
const exExam = id => exD().exams.find(e => e.id === id);
const exPaper = id => exD().papers.find(p => p.id === id);
const exMk = (D, pid, adm) => (D.marks[pid] || {})[adm];
const exSecKey = (pid, sec) => pid + '|' + sec;
const exMins = t => { const [h, m] = String(t || '0:0').split(':'); return (+h) * 60 + (+m); };
const exOverlap = (a, b) => exMins(a.start) < exMins(b.end) && exMins(b.start) < exMins(a.end);
const exSlotKey = p => p.date + ' ' + p.start;
function exCurExam(bid) { const L = exD().exams.filter(e => e.bid === bid); return L.find(e => e.id === App.ui.exId) || L[0] || null; }
/* effective result of one student in one paper, taking grace and supplementary into account */
function exPaperMark(D, p, s) {
  const st = (D.mst[exSecKey(p.id, s.sec)] || {}).state, mk = exMk(D, p.id, s.adm); if (!mk) return { state: 'none' };
  const out = { state: st || 'Entered', ab: !!mk.ab, m: mk.ab ? 0 : (+mk.m || 0), grace: +mk.grace || 0 }; out.eff = out.m + out.grace; out.pass = !out.ab && out.eff >= p.pass; return out;
}
function exResults(e) {
  const D = exD(), P = D.papers.filter(p => p.eid === e.id), bid = e.bid, secs = acSections(bid).filter(s => e.classes.includes(s.cls)), out = [];
  const sup = D.exams.filter(x => x.kind === 'Supplementary' && x.parent === e.id);
  secs.forEach(sc => lmRoster(bid, sc.cls, sc.sec).forEach(s => {
    const PP = P.filter(p => p.cls === sc.cls); if (!PP.length) return; let complete = true, tot = 0, max = 0; const rows = PP.map(p => {
      const r = exPaperMark(D, p, s); if (r.state !== 'Published') complete = false; let eff = r.eff || 0, pass = r.pass, supp = false;
      if (r.state === 'Published' && !pass) sup.forEach(x => D.papers.filter(q => q.eid === x.id && q.cls === p.cls && q.subject === p.subject).forEach(q => { const rr = exPaperMark(D, q, s); if (rr.state === 'Published' && rr.pass) { pass = true; supp = true; eff = D.cfg.suppCap ? Math.min(rr.eff, p.pass) : rr.eff; } }));
      tot += eff; max += p.max; return { p, r, eff, pass, supp };
    });
    const failed = rows.filter(x => !x.pass).length, pct = max ? Math.round(tot / max * 1000) / 10 : 0;
    out.push({ s, cls: sc.cls, sec: sc.sec, rows, tot, max, pct, failed, complete, result: !complete ? 'Pending' : failed === 0 ? (rows.some(x => x.supp) ? 'Pass (supplementary)' : 'Pass') : failed <= 2 ? 'Compartment' : 'Fail', grade: complete ? lmGrade(pct) : '—' });
  }));
  const bySec = {}; out.forEach(r => (bySec[r.cls + '|' + r.sec] = bySec[r.cls + '|' + r.sec] || []).push(r));
  Object.values(bySec).forEach(L => { const C = L.filter(r => r.complete).sort((a, b) => b.tot - a.tot); C.forEach((r, i) => { r.rank = i && C[i - 1].tot === r.tot ? C[i - 1].rank : i + 1; }); });
  return out;
}
