EX_ACT.exModerate = t => {
  const [pid, sec] = t.dataset.k.split('|'), p = exPaper(pid), D = exD(); if (!p || !exMgr()) return; const m = D.mst[exSecKey(pid, sec)]; if (m.by === App.user.name) return toast('The person who entered the marks cannot moderate them.', 'bad');
  const R = lmRoster(p.bid, p.cls, sec).filter(s => exMk(D, pid, s.adm));
  modal(`Moderation · ${p.cls} ${sec} · ${p.subject}`, `<p class="small">Pass mark ${p.pass}. Grace marks (up to ${D.cfg.graceMax}) may be given only to bring a failing student to the pass mark.</p><table class="tbl"><thead><tr><th>Student</th><th>Marks</th><th>Grace</th></tr></thead><tbody>${R.map((s, i) => { const k = exMk(D, pid, s.adm); const can2 = !k.ab && k.m < p.pass && p.pass - k.m <= D.cfg.graceMax; return `<tr><td>${esc(s.name)}</td><td>${k.ab ? 'AB' : k.m}</td><td>${can2 ? `<input id="mg_${i}" type="number" min="0" max="${p.pass - k.m}" value="${k.grace || 0}" style="width:70px">` : (k.grace || 0)}</td></tr>`; }).join('')}</tbody></table>`, `<button class="btn primary" data-act="exModOk" data-k="${esc(t.dataset.k)}">Confirm moderation</button><button class="btn" data-act="closeModal">Cancel</button>`, true);
};
EX_ACT.exModOk = t => {
  const [pid, sec] = t.dataset.k.split('|'), p = exPaper(pid), D = exD(), R = lmRoster(p.bid, p.cls, sec).filter(s => exMk(D, pid, s.adm)), gr = {}; let bad = '';
  R.forEach((s, i) => { const el = document.getElementById('mg_' + i); if (!el) return; const g = +el.value || 0, k = exMk(D, pid, s.adm); if (g < 0 || g > D.cfg.graceMax || k.m + g > p.pass) bad = `${s.name}: grace may be at most ${Math.min(D.cfg.graceMax, p.pass - k.m)} (to reach the pass mark).`; if (g !== (k.grace || 0)) gr[s.adm] = g; });
  if (bad) return toast(bad, 'bad'); const n = Object.keys(gr).length;
  askReason('Confirm moderation', n ? `${n} student${n === 1 ? '' : 's'} receive grace marks.` : 'No grace marks are being given.', async reason => { const d = Store.clone(exD()); Object.entries(gr).forEach(([a, g]) => { d.marks[pid][a].grace = g; }); const key = exSecKey(pid, sec); d.mst[key] = Object.assign(d.mst[key], { state: 'Moderated', mod: App.user.name, modAt: nowIso() }); exLog(d, p.bid, `Marks moderated: ${p.cls} ${sec} ${p.subject}`, { old: 'Entered', new: n ? `Moderated, grace for ${n}: ${Object.entries(gr).map(([a, g]) => a + '+' + g).join(', ')}` : 'Moderated, no grace' }, reason); await exSave(d); exAud(`Moderated ${key}`, { reason }); closeModal(); });
};
EX_ACT.exPublish = t => { const [pid, sec] = t.dataset.k.split('|'), p = exPaper(pid), key = exSecKey(pid, sec), m = exD().mst[key]; if (!p || !exMgr()) return; if (m.by === App.user.name) return toast('The person who entered the marks cannot publish them.', 'bad'); askReason('Publish marks', `${p.cls} ${sec} · ${p.subject}`, async reason => { const d = Store.clone(exD()); d.mst[key] = Object.assign(d.mst[key], { state: 'Published', pub: App.user.name, pubAt: nowIso() }); exLog(d, p.bid, `Marks published: ${p.cls} ${sec} ${p.subject}`, { old: 'Moderated', new: 'Published' }, reason); await exSave(d); exAud(`Published ${key}`, { reason }); rerender(); }); };
/* ---------- results, acknowledgement, report cards ---------- */
EX_ACT.exAck = t => { const { bid } = acBidSel(), e = exCurExam(bid), adm = t.dataset.k; if (!e) return; askReason('Record parent acknowledgement', `Parent of ${adm} has seen the result of ${e.name}.`, async reason => { const d = Store.clone(exD()); d.ack[e.id + '|' + adm] = { date: PROC_TODAY, by: App.user.name, note: reason }; exLog(d, bid, `Result acknowledged: ${adm}`, { new: PROC_TODAY }, reason); await exSave(d); rerender(); }); };
EX_ACT.exCards = async t => {
  const { bid } = acBidSel(), e = exCurExam(bid), key = t.dataset.k; if (!e) return; if (!window.jspdf) return toast('The PDF library did not load.', 'bad'); const R = exResults(e).filter(r => r.cls + '|' + r.sec === key && r.complete); if (!R.length) return toast('No complete results to print for this section yet.', 'bad');
  const doc = new window.jspdf.jsPDF({ unit: 'mm', format: 'a4' }); R.forEach((r, i) => {
    if (i) doc.addPage(); doc.setFontSize(15); doc.text('PROGRESS REPORT', 105, 18, { align: 'center' }); doc.setFontSize(10); doc.text((acBr(bid) || {}).name || '', 105, 25, { align: 'center' }); doc.text(`${e.name} · ${e.term} · ${CUR_AY}`, 105, 31, { align: 'center' });
    doc.setFontSize(11); doc.text(`Name: ${r.s.name}`, 15, 44); doc.text(`Admission no.: ${r.s.adm}`, 15, 51); doc.text(`Class: ${r.cls} ${r.sec}`, 110, 44); let y = 66; doc.setFontSize(10); doc.text('Subject', 15, y); doc.text('Maximum', 90, y); doc.text('Marks', 115, y); doc.text('Result', 145, y); doc.line(15, y + 2, 195, y + 2); y += 8;
    r.rows.forEach(x => { doc.text(x.p.subject, 15, y); doc.text(String(x.p.max), 90, y); doc.text(x.r.ab ? 'AB' : String(x.eff) + (x.supp ? ' (S)' : ''), 115, y); doc.text(x.pass ? 'Pass' : 'Fail', 145, y); y += 7; });
    doc.line(15, y, 195, y); y += 8; doc.setFontSize(11); doc.text(`Total: ${r.tot} / ${r.max}   Percentage: ${r.pct}%   Grade: ${r.grade}`, 15, y); y += 8; doc.text(`Result: ${r.result}   Rank in section: ${r.rank}`, 15, y);
    doc.setFontSize(10); doc.text('Class teacher', 15, 265); doc.text('Principal', 95, 265); doc.text('Parent signature', 160, 265);
  }); await saveFile(`report-cards-${e.name.replace(/\W+/g, '-')}-${key.replace('|', '-')}.pdf`, doc.output('blob')); exAud(`Report cards downloaded ${e.id} ${key}`, { new: R.length + ' cards' }); toast(`${R.length} report cards downloaded.`, 'ok');
};
/* ---------- remedial ---------- */
EX_ACT.exIntervGen = async t => {
  const e = exExam(t.dataset.k); if (!e) return; const d = Store.clone(exD()); let n = 0;
  exResults(e).filter(r => r.result === 'Compartment' || r.result === 'Fail').forEach(r => r.rows.filter(x => !x.pass).forEach(x => { if (d.interv.some(i => i.eid === e.id && i.adm === r.s.adm && i.subject === x.p.subject)) return; const al = acD().alloc.find(a => a.bid === e.bid && a.cls === r.cls && a.sec === r.sec && a.subject === x.p.subject); d.interv.push({ id: 'IV' + Date.now().toString(36) + n++, eid: e.id, bid: e.bid, adm: r.s.adm, name: r.s.name, cls: r.cls, sec: r.sec, subject: x.p.subject, teacher: al ? al.teacher : '', plan: `Remedial classes for ${x.p.subject}; ${r.result === 'Compartment' ? 'prepare for the supplementary examination' : 'reassess after the next unit test'}`, state: 'Planned', by: App.user.name, at: nowIso() }); }));
  if (!n) return toast('Remedial plans already exist for every failed subject.'); exLog(d, e.bid, `Remedial plans created: ${e.name}`, { new: n + ' plans' }, ''); await exSave(d);
};
EX_ACT.exIntervUpd = t => { const i = exD().interv.find(x => x.id === t.dataset.k); if (!i) return; modal(`Remedial plan · ${i.name}`, pcFld('Status', pcSel('iv_s', ['Planned', 'In progress', 'Completed'], i.state)) + pcFld('Progress note', '<input id="iv_n">'), `<button class="btn primary" data-act="exIntervOk" data-k="${i.id}">Save</button><button class="btn" data-act="closeModal">Cancel</button>`); };
EX_ACT.exIntervOk = async t => { const d = Store.clone(exD()), i = d.interv.find(x => x.id === t.dataset.k); if (!i) return; const old = i.state; i.state = v('iv_s'); i.note = (v('iv_n') || '').trim(); exLog(d, i.bid, `Remedial plan updated: ${i.name} ${i.subject}`, { old, new: i.state }, i.note); await exSave(d); closeModal(); };
/* ---------- setup ---------- */
EX_ACT.exCfgOk = () => {
  if (!exCan('Edit')) return; const pass = +v('xc_pass'), grace = +v('xc_grace'), inv = +v('xc_inv'); if (!(pass >= 20 && pass <= 60) || !(grace >= 0 && grace <= 10) || !(inv >= 10 && inv <= 60)) return toast('Check the values: pass mark 20–60%, grace 0–10 marks, 10–60 students per invigilator.', 'bad');
  askReason('Save examination rules', 'Applies to every branch. Papers already created keep their own pass marks.', async reason => { const d = Store.clone(exD()), old = JSON.stringify(d.cfg); d.cfg = { pass, graceMax: grace, perInv: inv, blockOverdue: v('xc_block') === 'Yes', suppCap: v('xc_cap') === 'Yes' }; exLog(d, '', 'Examination rules changed', { old, new: JSON.stringify(d.cfg) }, reason); await exSave(d); exAud('Examination rules changed', { old, new: JSON.stringify(d.cfg), reason }); toast('Saved.', 'ok'); });
};
EX_ACT.exRoomAdd = async () => { const { bid } = acBidSel(), name = (v('xr_n') || '').trim(), cap = +v('xr_c'); if (!exCan('Edit')) return; if (!name || !(cap >= 5)) return toast('Enter the room name and its capacity.', 'bad'); const d = Store.clone(exD()); d.rooms[bid] = d.rooms[bid] || []; if (d.rooms[bid].some(r => r.name.toLowerCase() === name.toLowerCase())) return toast('A room with this name already exists.', 'bad'); d.rooms[bid].push({ id: 'RM' + Date.now().toString(36), name, cap }); exLog(d, bid, `Room added: ${name}`, { new: cap + ' seats' }, ''); await exSave(d); };
EX_ACT.exRoomDel = t => { const { bid } = acBidSel(), r = ((exD().rooms[bid]) || []).find(x => x.id === t.dataset.k); if (!r || !exCan('Edit')) return; if (exD().seats.some(s => s.room === r.name && exD().exams.some(e => e.id === s.eid && e.bid === bid))) return toast('This room is used in a seating plan.', 'bad'); askReason('Remove room', r.name, async reason => { const d = Store.clone(exD()); d.rooms[bid] = d.rooms[bid].filter(x => x.id !== r.id); exLog(d, bid, `Room removed: ${r.name}`, { old: r.cap + ' seats' }, reason); await exSave(d); rerender(); }); };
